fn binary_search_recursive(v: &[i32], elem: i32, c: isize, f: isize) -> isize {
    // Convert isize to usize for indexing
    let c = c as usize;
    let f = f as usize;

    // Base case: if the lower index exceeds the upper index
    if c > f {
        return -1; // No valid index found
    }

    // Calculate the mid index
    let mid = c + (f - c) / 2;

    // Check the value at mid
    if v[mid] <= elem {
        // If the value at mid is less than or equal to the target,
        // search in the right half (including mid)
        let result = binary_search_recursive(v, elem, mid + 1, f as isize);
        // If we found a valid index in the right half, return it
        // Otherwise, return mid
        return if result != -1 { result } else { mid as isize };
    } else {
        // If the value at mid is greater than the target,
        // search in the left half (excluding mid)
        return binary_search_recursive(v, elem, c as isize, mid as isize - 1);
    }
}

